transition.action:
entity e = new Entity(entityCount);
output.out = e;
entityCount = entityCount + 1;
schedule(nextArrival(), "generate");

function.body:
if (distributionType == "exponential") {
  return exponential(interArrivalTime);
} else if (distributionType == "uniform") {
  return uniform(0, 2 * interArrivalTime);
} else {
  return interArrivalTime;
}
